    /// <summary>Resolves the conversion error message (EditModelMessages.ParseFailed first, then fine-tuned by CustomizeParseErrorMessage).</summary>
    private string ResolveParseErrorMessage(
        string propertyName,
        string displayName,
        string inputValue,
        string typeName
